arguments.newString:
def _sanitize_value_amount(val: Optional[float], *, min_amount: float = 100_000) -> Optional[float]:
    if val is None:
        return None
    try:
        f = float(val)
    except (TypeError, ValueError):
        return None
    # ``min_amount`` is the smallest accepted value, so the floor is inclusive.
    # This matches resolve_appraisal_value(), which accepts ``value >= 100_000``.
    return f if f >= min_amount else None

